package com.login.demo.controller.api;
import com.login.demo.model.entity.Mesa; import com.login.demo.repository.MesaRepository; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/mesas") public class MesaApiController { private final MesaRepository repo; public MesaApiController(MesaRepository repo){this.repo=repo;} @GetMapping public List<Mesa> listar(){return repo.findAll();} @GetMapping("/{id}") public Optional<Mesa> ver(@PathVariable Integer id){return repo.findById(id);} @PostMapping public Mesa crear(@RequestBody Mesa m){return repo.save(m);} @PutMapping("/{id}") public Mesa actualizar(@PathVariable Integer id,@RequestBody Mesa m){m.setId(id);return repo.save(m);} @DeleteMapping("/{id}") public void eliminar(@PathVariable Integer id){repo.deleteById(id);} }
